// v23.xx (gfx12), HIS ORDER (2026-10-12) on the graphics program, item 1, real lighting, on COLD STORAGE (the one map, his beta
// spec): THE DISTRICTS ARE LIT LIKE WHAT THEY ARE. The lamps were one or two per building in the district colour and posts by
// walls, the same everywhere. Three authored sets are added on top, live raids only, with no random number drawn (a fixed grid
// over each district, a point kept only where it is clear of every wall), so the seeded map and every count measured on it are
// untouched: cold white strip lights hung over the PACKING FLOOR aisles every 250 units, sickly green lamps that flicker in THE
// SUMP, and big sodium floods on posts along the walls of the SCRAP LINE. A lamp that lands in water is culled after, as every
// lamp is (v2.86). A blackout raid has none of them. Light never feeds the sim (detection, sight and sound are untouched).
var COLDLIGHTS=[
  {id:'cs_pack',  step:250, r:150, c:'#cfeeff', i:.34, fl:false, pad:24, wall:0,   post:0},
  {id:'cs_sump',  step:280, r:165, c:'#b8e08a', i:.30, fl:true,  pad:24, wall:0,   post:0},
  {id:'cs_scrap', step:420, r:250, c:'#ffd29a', i:.40, fl:false, pad:30, wall:140, post:1}
];
function gfxColdLights(map,lights){
  var s, S, R, k, x, y, q, w, ok, near, nx, ny, n=0, f=0, ws=(map&&map.walls)||[], lm=(map&&map.landmarks)||[];
  for(s=0;s<COLDLIGHTS.length;s++){
    S=COLDLIGHTS[s]; R=null;
    for(k=0;k<lm.length;k++) if(lm[k]&&lm[k].id===S.id) R=lm[k];
    if(!R) continue;
    for(y=R.y+S.step/2;y<R.y+R.h;y+=S.step) for(x=R.x+S.step/2;x<R.x+R.w;x+=S.step){
      ok=true; near=!S.wall;
      for(q=0;q<ws.length;q++){
        w=ws[q];
        if(x>w.x-S.pad&&x<w.x+w.w+S.pad&&y>w.y-S.pad&&y<w.y+w.h+S.pad){ ok=false; break; }
        if(!near&&!(w.tree||w.furn||w.wreck||w.ruin||w.win)){ nx=clamp(x,w.x,w.x+w.w); ny=clamp(y,w.y,w.y+w.h); if((x-nx)*(x-nx)+(y-ny)*(y-ny)<S.wall*S.wall) near=true; }
      }
      if(!ok||!near) continue;
      f++;
      lights.push(S.post?{x:x,y:y,r:S.r,c:S.c,i:S.i,f:(f*1.7)%9,fl:S.fl,post:1,cold:S.id}:{x:x,y:y,r:S.r,c:S.c,i:S.i,f:(f*1.7)%9,fl:S.fl,cold:S.id});
      n++;
    }
  }
  return n;
}
function gfxLightFail(e){

// v23.xx (gfx12): COLD STORAGE's authored light sets, live only, no random number drawn (gfxColdLights)
if(!sim&&!hasTerm('blackout')&&map.fixed==='cold'&&CFG.coldLights!==0) gfxColdLights(map,lights);
// NO LAMPS STANDING IN WATER, v2.86, the same cull family as the map pass:

check:
{v:'VER',what:'graphics program gfx12: COLD STORAGE light placement: a live raid on map 0 has cold strip lights hung clear of every wall inside the PACKING FLOOR (6 or more, on its 250 unit aisle grid), flickering lamps in THE SUMP and posted floods on the SCRAP LINE beside a wall, a bot raid keeps no lamps at all, and the seed 4242 raid keeps its entity and container counts with the lights on or off',
 run:function(){
   if(!(window.__deploy&&window.__state&&window.__endRaid&&window.__simRaidBegin&&window.__simRaidEnd)) return 'SKIP: this fixture cannot deploy';
   if(typeof gfxColdLights!=='function'||typeof COLDLIGHTS==='undefined') return 'no COLD STORAGE light sets: gfxColdLights missing';
   var bad=[], g, ls, pack, sump, scrap, R={}, i, k, w, ws, cl0=CFG.coldLights, n1, n0, c1, c0, sl;
   try{
     __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
     __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     g=__state(); if(!g||g.over) return 'SKIP: no live raid';
     if(g.map.fixed!=='cold') return 'SKIP: map 0 is not COLD STORAGE here';
     ls=g.lights; ws=g.map.walls;
     for(i=0;i<g.map.landmarks.length;i++) R[g.map.landmarks[i].id]=g.map.landmarks[i];
     pack=ls.filter(function(L){ return L.cold==='cs_pack'; });
     sump=ls.filter(function(L){ return L.cold==='cs_sump'; });
     scrap=ls.filter(function(L){ return L.cold==='cs_scrap'; });
     if(pack.length<6) bad.push('only '+pack.length+' strip lights on the PACKING FLOOR (want 6 or more)');
     pack.forEach(function(L){
       var P0=R.cs_pack; if(!(L.x>P0.x&&L.x<P0.x+P0.w&&L.y>P0.y&&L.y<P0.y+P0.h)) bad.push('a PACKING FLOOR light at '+L.x+','+L.y+' is outside it');
       if(Math.abs(((L.x-P0.x)-125)%250)>0.5||Math.abs(((L.y-P0.y)-125)%250)>0.5) bad.push('a PACKING FLOOR light at '+L.x+','+L.y+' is off the aisle grid');
       for(k=0;k<ws.length;k++){ w=ws[k]; if(L.x>w.x-20&&L.x<w.x+w.w+20&&L.y>w.y-20&&L.y<w.y+w.h+20){ bad.push('a PACKING FLOOR light at '+L.x+','+L.y+' hangs on a wall'); break; } }
     });
     if(!sump.length) bad.push('no lamps in THE SUMP');
     else if(sump.some(function(L){ return !L.fl; })) bad.push('a SUMP lamp does not flicker');
     if(!scrap.length) bad.push('no floods on the SCRAP LINE');
     else if(scrap.some(function(L){ return !L.post; })) bad.push('a SCRAP LINE flood is not on a post');
     n1=g.ents.length; c1=g.containers.length;
     __endRaid('abandon'); __topClear();
     CFG.coldLights=0;
     __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     g=__state();
     if(g&&!g.over){
       n0=g.ents.length; c0=g.containers.length;
       if(g.lights.some(function(L){ return !!L.cold; })) bad.push('coldLights 0 still hangs the authored lights');
       if(n0!==n1||c0!==c1) bad.push('the authored lights moved the seeded raid: ents '+n1+' against '+n0+', containers '+c1+' against '+c0);
       __endRaid('abandon'); __topClear();
     }
     CFG.coldLights=cl0;
     __simRaidBegin(4242); sl=__state()?__state().lights.length:-1; __simRaidEnd();
     if(sl!==0) bad.push('a bot raid has '+sl+' lamps');
   }catch(err){ bad.push('threw: '+(err&&err.message||err)); }
   finally{
     CFG.coldLights=cl0;
     try{ var g2=__state(); if(g2&&!g2.over&&!g2.sim) __endRaid('abandon'); }catch(_e){}
     __topClear(); __cleanProfile();
   }
   return bad.length?bad.join('; '):null; }},
